SELECT  o.*,   i.title AS itemName,  i.image_url AS itemImage   FROM order_info o
LEFT JOIN item i ON o.item_id = i.id  WHERE o.buyer_id = #{buyerId}
ORDER BY o.create_time DESC

SELECT o.*, i.title AS itemName, i.image_url AS itemImage FROM order_info o LEFT JOIN item i ON o.item_id = i.id WHERE o.buyer_id = #{buyerId}
AND o.status = #{status}
ORDER BY o.create_time DESC

SELECT * FROM order_info
WHERE status = #{status}
  AND create_time < DATE_SUB(NOW(), INTERVAL #{minutes} MINUTE)

SELECT o.*, i.title AS itemName, i.image_url AS itemImage
FROM order_info o
LEFT JOIN item i ON o.item_id = i.id
WHERE o.buyer_id = #{buyerId}

    AND o.status = #{status}

AND (
o.order_no LIKE concat('%', #{keyword}, '%')
OR i.title LIKE concat('%', #{keyword}, '%')
)
ORDER BY o.create_time DESC

SELECT o.*, i.title AS itemName, i.image_url AS itemImage FROM order_info o JOIN item i ON o.item_id = i.id WHERE i.seller_id = #{sellerId}
AND o.status = #{status}
ORDER BY o.create_time DESC

SELECT o.*, i.title AS itemName, i.image_url AS itemImage
FROM order_info o
JOIN item i ON o.item_id = i.id
WHERE i.seller_id = #{sellerId}

    AND o.status = #{status}

AND (
o.order_no LIKE concat('%', #{keyword}, '%')
OR i.title LIKE concat('%', #{keyword}, '%')
)
ORDER BY o.create_time DESC
